import{G as e,W as t,rt as n,t as r}from"./chunks/framework.3zKPIMIf.js";var i=JSON.parse(`{"title":"Privacy Policy","description":"","frontmatter":{},"headers":[],"relativePath":"privacy-policy.md","filePath":"privacy-policy.md"}`),a={name:`privacy-policy.md`};function o(r,i,a,o,s,c){return n(),t(`div`,null,[...i[0]||=[e(`<h1 id="privacy-policy" tabindex="-1">Privacy Policy <a class="header-anchor" href="#privacy-policy" aria-label="Permalink to “Privacy Policy”">​</a></h1><p>cBlock collects no data at all.</p><ul><li>cBlock uses no server.</li><li>cBlock reads page text only inside your browser and never sends it anywhere, including to cBlock’s developers.</li><li>Settings and lookup results are saved only in your browser, and are deleted when you remove the extension.</li></ul><h2 id="website-lookups" tabindex="-1">Website lookups <a class="header-anchor" href="#website-lookups" aria-label="Permalink to “Website lookups”">​</a></h2><p>When you turn on any of the “Website lookups” in Options, cBlock asks the website you’re on about items on the page, to judge more accurately.</p><p>For example, Amazon search results don’t show the seller’s location, and Steam search results don’t show the developer or publisher. Likewise, X posts don’t show the author’s location, and pixiv works don’t show the artist’s location. So cBlock asks the website for what the page doesn’t show, and judges from the answer.</p><p><strong>All of these are off by default.</strong></p><table tabindex="0"><thead><tr><th>Website</th><th>What cBlock sends</th><th>Why</th><th>Where it goes</th></tr></thead><tbody><tr><td><strong>Amazon</strong></td><td>A product ID and a seller ID</td><td>To find the seller’s address, phone, and name</td><td>The Amazon website you’re on</td></tr><tr><td><strong>Steam</strong></td><td>A game ID</td><td>To find the developer and publisher</td><td><code>store.steampowered.com</code></td></tr><tr><td><strong>X</strong></td><td>The handle of a shown post’s author</td><td>To find the author’s account location and connection source</td><td><code>x.com</code></td></tr><tr><td><strong>pixiv</strong></td><td>The artist ID of a shown work</td><td>To find the artist’s profile</td><td><code>www.pixiv.net</code></td></tr></tbody></table><ul><li>cBlock asks only the website you’re on, and sends nothing to cBlock’s developers or anyone else.</li><li>To avoid asking the same thing again, lookup results are saved in your browser for 30 days.</li></ul>`,9)]])}var s=r(a,[[`render`,o]]);export{i as __pageData,s as default};